/*
 * A383271  Number of primes (excluding n) that may be generated by replacing
 *          any binary digit of n with a digit from 0 to 1.
 * https://oeis.org/A383271
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, base
 * Formula:   not stated
 * Range:     u8 n <= 10000, u16 n <= 10000, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   is_prime
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* Computation: number of primes obtainable by toggling one binary digit of n */

/* This function uses the helper is_prime(idx_t) defined in ../utils/is_prime.h */
#include <stdbool.h>
#include "../utils/is_prime.h"

/* a(n) = number of primes generated by flipping a single binary bit of n */
seq_t a(idx_t n)
{
    /* n == 0 gives no neighbors */
    if (n == 0)
        return (seq_t)0;

    /* determine number of bits in the minimal binary representation of n */
    idx_t tmp = n;
    idx_t bits = 0;
    while (tmp > 0) {
        bits++;
        tmp >>= 1;
    }

    /* count primes among all numbers obtained by toggling each bit */
    idx_t count = 0;
    for (idx_t k = 0; k < bits; ++k) {
        idx_t neighbor = n ^ ((idx_t)1 << k);
        if (is_prime(neighbor))
            ++count;
    }

    return (seq_t)count;
}
